        AND USER_ADDR LIKE CONCAT('%', #{userSearchVO.user_addr}, '%')


        AND USER_EMAIL LIKE CONCAT('%', #{userSearchVO.user_email}, '%')


LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

